begin;
insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata)
values
(
'social-studies','a2-social-groups','a2-society-governance','14–17. Social Groups, Cohesion, Control and Interaction','Understand how groups are organised, how cohesion is maintained and how people interact within and among groups.',10,true,
'{"syllabus":{"section":"A","part":"ii","objectives":["14","15","16","17a","17b","17c"],"source":"CXC 14/G/SYLL 22"},"lesson":{"objectives":["Classify primary, secondary, formal, informal, peer, interest, voluntary and involuntary groups.","Explain leadership, control, cooperation, authority, commitment and loyalty as requirements for cohesion.","Distinguish folkways, norms, mores, rules, laws and sanctions.","Explain competition, conflict, creativity, cooperation and compromise in group interaction.","Design an observation checklist and show respect for differences among group members."],"introduction":"A social group is more than a collection of people in the same place. Members interact, recognise some connection, and usually share needs, interests, values, goals or rules. A school class, football club, church youth group and close friendship circle can all be groups, but they do not have the same structure.","sections":[{"title":"Types of social groups","bullets":["Primary groups are usually small and built on close, personal relationships, such as a close friendship circle.","Secondary groups are more impersonal and organised around a purpose, such as a school or workplace committee.","Formal groups have established structures, rules and recognised roles.","Informal groups develop naturally with fewer written rules.","Peer groups bring together people of similar age or status.","Interest groups organise around a shared concern or activity.","Membership may be voluntary, chosen by the person, or involuntary, entered without a free choice."]},{"title":"What makes a group a group","bullets":["A structure or pattern of roles.","Common goals, needs, interests or values.","Marks of identity such as a name, uniform, badge, slogan or shared practices.","Ways of interacting that are shaped by rules and expectations.","Patterns of behaviour and cooperation.","Sanctions that reward conformity or respond to unacceptable behaviour."]},{"title":"Cohesion","paragraphs":["Cohesion is the strength of the bonds that help a group stay together and work toward its purposes. Leadership provides direction. Authority gives recognised power to make decisions. Control helps maintain standards. Cooperation allows members to combine effort. Commitment keeps members engaged, while loyalty supports the group during difficulty.","Cohesion does not mean members must agree about everything. Healthy groups can manage disagreement without destroying relationships or silencing legitimate criticism."]},{"title":"Social control","paragraphs":["Groups and societies guide behaviour through folkways, norms, mores, rules, laws and sanctions. Folkways are everyday customary behaviours. Norms are shared expectations. Mores are strongly held norms linked to moral judgement. Rules are explicit requirements within an organisation, while laws are formally enacted and enforced by the state.","Sanctions may be positive, such as praise or a certificate, or negative, such as a warning, suspension or legal penalty."]},{"title":"Interaction and respect","paragraphs":["People cooperate, compete, compromise, solve problems and sometimes experience conflict. Differences in class, education, ethnicity, gender, beliefs or disability can affect group experiences. Respect means recognising another person''s dignity and rights even when opinions or backgrounds differ."]},{"title":"Observation checklists","paragraphs":["An observation checklist records behaviours that can actually be seen or heard. Items must be clear, specific and observable, with room for notes where useful. A weak item such as ''member has a good attitude'' is vague. A stronger item is ''member allows others to finish speaking before responding''. Consent and privacy still matter."]}],"keyPoints":["Primary and secondary describe relationship patterns; formal and informal describe degree of organisation.","Cohesion depends on leadership, control, cooperation, authority, commitment and loyalty.","Social control operates through expectations, rules, laws and sanctions.","Conflict is one form of interaction and can be managed through communication, compromise or mediation.","Observation items should describe behaviour that can actually be observed."],"summary":"Do not classify groups from their names alone. Look at relationships, structure, membership and purpose. For research questions, write observations that another person could identify in the same way.","flashcards":[{"front":"What is a primary group?","back":"A usually small group based on close, personal and lasting relationships."},{"front":"What is a formal group?","back":"A group with recognised structure, roles, rules and procedures."},{"front":"What is group cohesion?","back":"The bonds and conditions that help members remain united and pursue group goals."},{"front":"What is a positive sanction?","back":"A reward or approval used to encourage behaviour that meets group expectations."},{"front":"What is a more?","back":"A strongly held social norm connected to moral judgement."},{"front":"Name five forms of group interaction.","back":"Competition, conflict, creativity/problem-solving, cooperation and compromise."},{"front":"What makes an observation-checklist item strong?","back":"It is clear, specific, observable and not open to vague interpretation."}],"interactiveModels":[{"id":"a2-group-classifier","type":"social-studies","mode":"classify","title":"Social Group Sorter","categories":["Primary","Secondary","Formal","Informal"],"items":[{"label":"A close circle of lifelong friends","category":"Primary","explanation":"The relationships are personal and emotionally close."},{"label":"A school student council with elected officers and a constitution","category":"Formal","explanation":"It has recognised structure, roles and procedures."},{"label":"A temporary committee planning a community clean-up","category":"Secondary","explanation":"It is organised mainly around a specific task or purpose."},{"label":"Students who naturally meet under the same tree at lunch","category":"Informal","explanation":"The group develops without formal rules or official structure."}]}]}}'::jsonb
),
(
'social-studies','a2-social-institutions','a2-society-governance','18–19. Social Institutions and Their Functions','Examine family, educational, religious, recreational, economic and political institutions and evaluate what they do for society.',20,true,
'{"syllabus":{"section":"A","part":"ii","objectives":["18","19"],"source":"CXC 14/G/SYLL 22"},"lesson":{"objectives":["Identify major types of social institutions.","Outline characteristics shared by institutions.","Evaluate economic, educational, socialising, religious, political and recreational functions.","Explain how institutions depend on one another."],"introduction":"Institutions are established ways society organises important needs. The word can refer to broad systems such as education or government and also to organisations that embody those systems, such as a school or parliament. The important idea is that institutions persist, develop rules and values, and perform recognised functions.","sections":[{"title":"Types named in the syllabus","bullets":["Family institution: care, socialisation, reproduction and support.","Educational institution: schools, colleges and training bodies that develop knowledge, skills and social behaviour.","Religious institution: organisations and traditions concerned with faith, worship and moral or spiritual life.","Recreational institution: organisations such as sports clubs that support recreation and well-being.","Economic institution: organisations and systems involved in production, finance and exchange, such as banks.","Political institution: government and related bodies that make and implement public decisions."]},{"title":"Characteristics of institutions","bullets":["They reflect norms, mores, laws and values.","They tend to endure over time, although they can change.","They influence how society works.","They usually have recognised functions, rules, sanctions, symbols and rituals.","Organisations within institutions often have a hierarchy or defined structure."]},{"title":"Institutions work together","paragraphs":["A school cannot function without families, government, economic resources and community support. A bank depends on laws and regulation. A sports club may rely on schools for young athletes and on businesses for sponsorship. This interdependence is a useful point in extended-response questions."]},{"title":"Evaluate, do not only list","paragraphs":["To evaluate a function, explain its value and consider how effectively it meets a need. For example, saying ''schools educate'' is a starting point. A stronger answer explains that education develops knowledge and skills needed for employment and citizenship, while access, quality and relevance affect how well this function is performed."]}],"keyPoints":["Institutions organise important and recurring needs in society.","Institutions endure but can change as values and needs change.","Functions may be economic, educational, socialising, religious, political or recreational.","Institutions are interdependent."],"summary":"In an evaluation question, go beyond naming a function. Explain its contribution and, where relevant, a limitation or condition affecting its effectiveness.","flashcards":[{"front":"Name six types of social institution.","back":"Family, educational, religious, recreational, economic and political."},{"front":"Why are institutions described as enduring?","back":"They continue over time even though their rules and forms may change."},{"front":"Give one educational function of institutions.","back":"Developing knowledge, skills and the human resources of society."},{"front":"What is institutional interdependence?","back":"Institutions rely on and affect one another while meeting society''s needs."},{"front":"Why do institutions use sanctions?","back":"To encourage compliance with rules, values and expected behaviour."}],"interactiveModels":[{"id":"a2-institution-match","type":"social-studies","mode":"classify","title":"Institution and Function Match","categories":["Educational","Economic","Political","Recreational","Religious","Family"],"items":[{"label":"A commercial bank provides savings accounts and loans.","category":"Economic"},{"label":"A secondary school teaches academic and vocational skills.","category":"Educational"},{"label":"A parliament debates and passes legislation.","category":"Political"},{"label":"A football club organises training and competition.","category":"Recreational"},{"label":"A church youth ministry provides worship and moral guidance.","category":"Religious"},{"label":"Caregivers teach a child everyday values and behaviour.","category":"Family"}]}]}}'::jsonb
),
(
'social-studies','a2-government-forms-systems','a2-society-governance','20. Forms and Systems of Government','Distinguish democracy from autocracy and compare Crown Colony, constitutional monarchy and republic systems in the Commonwealth Caribbean context.',30,true,
'{"syllabus":{"section":"A","part":"ii","objectives":["20a","20b"],"source":"CXC 14/G/SYLL 22"},"lesson":{"objectives":["Differentiate democracy and autocracy using clear characteristics.","Distinguish Crown Colony, constitutional monarchy and republic as government systems.","Separate the idea of a form of government from the identity of a head of state.","Use neutral evidence when comparing political systems."],"introduction":"Government describes the institutions and people authorised to make and carry out public decisions. CSEC asks students to distinguish broad forms of government and government systems found in Caribbean history and contemporary society.","sections":[{"title":"Democracy and autocracy","paragraphs":["In a democracy, political authority is based on participation by citizens through mechanisms such as elections and representative institutions, and government power is subject to rules and accountability. In an autocracy, political power is concentrated in one ruler or a small centre of authority with limited effective public control over leadership.","These are analytical categories. A good answer identifies features rather than using the terms as insults or praise."]},{"title":"Crown Colony","paragraphs":["A Crown Colony system historically placed significant governing authority in officials representing the British Crown. Caribbean constitutional development moved many territories away from this colonial structure toward internal self-government and independence."]},{"title":"Constitutional monarchy","paragraphs":["In a constitutional monarchy, a monarch is head of state under constitutional rules, while elected institutions and the government exercise political authority according to the constitution. Several Commonwealth Caribbean states have used this model."]},{"title":"Republic","paragraphs":["In a republic, the head of state is not a hereditary monarch. The constitution sets out how the president or other republican head of state is selected and what powers the office holds. Different republics can have different constitutional arrangements."]},{"title":"How to compare systems","paragraphs":["Compare the source of authority, selection of the head of state, role of the constitution and relationship between elected institutions and executive power. Avoid assuming that the title ''president'' or ''monarch'' alone tells you how much power that office has."]}],"keyPoints":["Democracy and autocracy describe how political power is organised and controlled.","A constitutional monarchy has a monarch as head of state within constitutional limits.","A republic has a non-hereditary head of state.","Constitutions determine the actual powers and relationships among offices."],"summary":"Use constitutional features, not labels alone. CSEC questions often reward clear distinctions supported by accurate characteristics.","flashcards":[{"front":"What is a democracy?","back":"A system where public authority is subject to citizen participation, rules and accountability."},{"front":"What is an autocracy?","back":"A form of government where political power is concentrated with limited public control."},{"front":"What is a constitutional monarchy?","back":"A system with a monarch as head of state operating within constitutional rules."},{"front":"What makes a state a republic?","back":"Its head of state is not a hereditary monarch."},{"front":"Why can two republics differ greatly?","back":"Their constitutions can assign different powers and selection methods to political offices."}],"interactiveModels":[{"id":"a2-government-system-check","type":"social-studies","mode":"choice","title":"Government Systems: Read the Features","items":[{"prompt":"A constitution provides for an elected legislature while a monarch remains ceremonial head of state. Which system best fits?","choices":["Autocracy","Constitutional monarchy","Crown Colony","Direct democracy"],"correctIndex":1,"explanation":"The monarch remains head of state but government operates under constitutional arrangements."},{"prompt":"Which feature most clearly identifies a republic?","choices":["It holds elections","It has courts","Its head of state is not a hereditary monarch","It has political parties"],"correctIndex":2,"explanation":"Elections and courts can exist in several systems; the non-hereditary head of state is the key distinction here."}]}]}}'::jsonb
),
(
'social-studies','a2-government-structure-functions','a2-society-governance','21–22. Structure and Functions of Government','Learn separation of powers, the legislature, executive and judiciary, local government, security systems and the functions government performs.',40,true,
'{"syllabus":{"section":"A","part":"ii","objectives":["21","22"],"source":"CXC 14/G/SYLL 22"},"lesson":{"objectives":["Outline the principle of separation of powers.","Describe the legislature, executive and judiciary.","Explain the roles of the civil service, security systems and local government.","Evaluate economic, social, infrastructural, security, international and regulatory functions of government."],"introduction":"Government is not one single office. Modern states divide responsibilities among institutions. Understanding who makes laws, who carries out policy and who interprets law helps students analyse how public decisions are made and checked.","sections":[{"title":"Separation of powers","paragraphs":["The principle of separation of powers distinguishes the legislature, executive and judiciary. The exact constitutional arrangement differs among states, but the principle helps prevent all public power from being concentrated in one place.","The arms also interact. A legislature may pass a law, the executive administer it, and the judiciary interpret it in a dispute."]},{"title":"Legislature","bullets":["Debates and passes legislation.","Represents constituencies or the wider public according to the constitutional system.","Scrutinises government activity, including through opposition members and committees.","Participates in national budgeting and public accountability."]},{"title":"Executive and civil service","paragraphs":["The executive directs government policy and administration. Ministers or other executive officials make policy decisions within their legal authority. The civil service supports continuity by administering programmes, keeping records, providing technical advice and delivering public services."]},{"title":"Judiciary and security systems","paragraphs":["The judiciary interprets and applies law and resolves disputes. Courts must be understood within the legal system of the territory. Security institutions such as police and prison services help maintain law and order; some territories also participate in regional security arrangements."]},{"title":"Local government","paragraphs":["Local bodies may include municipal corporations, city or town councils, village councils or other arrangements depending on the territory. They handle public functions that are better organised close to communities."]},{"title":"Functions of government","bullets":["Economic: taxation, budgeting, employment policy, development and resource management.","Social services: health, welfare and related support.","Infrastructure: roads, public buildings and utilities.","Security: law and order and national defence.","International relations: representing the state and managing relations with other countries and organisations.","Regulation: setting and enforcing standards for public and economic life."]}],"keyPoints":["Separation of powers distinguishes legislature, executive and judiciary.","The legislature makes laws, the executive administers policy, and the judiciary interprets law.","The civil service supports implementation and continuity of government.","Government functions include economic management, services, infrastructure, security, international relations and regulation."],"summary":"When asked to explain a government function, connect the action to a public need. For structure questions, state what each arm does and how the arms interact without collapsing them into one.","flashcards":[{"front":"What does the legislature mainly do?","back":"Debates and passes laws and represents the public within the constitutional system."},{"front":"What does the executive mainly do?","back":"Directs policy and administers the work of government."},{"front":"What does the judiciary mainly do?","back":"Interprets and applies law and resolves legal disputes."},{"front":"What is separation of powers?","back":"The division of state functions among legislature, executive and judiciary."},{"front":"What is one role of the civil service?","back":"Administering public programmes and supporting continuity of government."},{"front":"Name three government functions.","back":"Examples: economic management, social services, infrastructure, security or regulation."}],"interactiveModels":[{"id":"a2-three-arms","type":"social-studies","mode":"classify","title":"Which Arm of Government?","categories":["Legislature","Executive","Judiciary"],"items":[{"label":"Debates a proposed law before it is passed.","category":"Legislature"},{"label":"A ministry implements a new public-health programme.","category":"Executive"},{"label":"A court interprets whether a law applies in a dispute.","category":"Judiciary"},{"label":"Members question government spending during a parliamentary sitting.","category":"Legislature"},{"label":"Public officers administer an approved government policy.","category":"Executive"}]}]}}'::jsonb
),
(
'social-studies','a2-citizens-constitution','a2-society-governance','23. Citizens, Government, Rights and the Constitution','Examine the constitutional relationship between citizens and government, including rights, responsibilities, voting and mechanisms for redress.',50,true,
'{"syllabus":{"section":"A","part":"ii","objectives":["23"],"source":"CXC 14/G/SYLL 22"},"lesson":{"objectives":["Define constitution, democracy and authoritarian government in syllabus context.","Explain the relationship between rights, freedoms and responsibilities.","Explain adult suffrage and the civic significance of voting rights.","Describe the role of an Ombudsman or similar regulatory authority as a channel for complaints and accountability."],"introduction":"A constitution sets out fundamental rules about how a state is governed. It can establish institutions, distribute powers and protect rights. Citizenship therefore involves both protections that people can claim and responsibilities they owe to others and society.","sections":[{"title":"Constitution","paragraphs":["A constitution is the fundamental framework of rules and principles by which a state is governed. It identifies institutions and powers and may entrench rights and procedures for changing constitutional arrangements."]},{"title":"Rights, freedoms and responsibilities","paragraphs":["Rights protect important interests and freedoms. Responsibilities remind citizens that exercising freedom takes place in a society where other people also have rights. Freedom of expression, for example, does not create a licence to threaten others or ignore lawful restrictions.","In exam answers, show the relationship: government has obligations to respect and protect lawful rights, while citizens are expected to obey valid laws, respect others and participate responsibly."]},{"title":"Adult suffrage","paragraphs":["Adult suffrage is the right of eligible adults to vote, subject to lawful qualifications such as citizenship, registration and age requirements. It is a key mechanism for political participation in representative democracy."]},{"title":"Redress and oversight","paragraphs":["An Ombudsman or other regulatory authority can provide a channel for investigating complaints about public administration, depending on the legal arrangements of the territory. The exact powers vary, so distinguish the general accountability role from territory-specific procedures."]}],"keyPoints":["A constitution establishes fundamental rules for government.","Rights and responsibilities are connected.","Adult suffrage refers to the right of eligible adults to vote.","Independent or specialised oversight bodies can help citizens seek redress for administrative problems."],"summary":"Avoid treating rights as unlimited or responsibilities as optional slogans. Explain the constitutional relationship between public power, individual freedom and accountability.","flashcards":[{"front":"What is a constitution?","back":"The fundamental framework of rules and principles by which a state is governed."},{"front":"What is adult suffrage?","back":"The right of eligible adults to vote under the law."},{"front":"Why are rights linked to responsibilities?","back":"People exercise freedoms in a society where others also have rights that must be respected."},{"front":"What is the general role of an Ombudsman?","back":"To receive or investigate complaints and support accountability in public administration."}],"interactiveModels":[{"id":"a2-right-responsibility","type":"social-studies","mode":"choice","title":"Rights and Responsibilities","items":[{"context":"A student says freedom of expression means nobody may ever criticise or limit anything a person says.","prompt":"What is the best response?","choices":["Correct; every form of speech is unlimited","Rights operate within law and alongside the rights of others","Only government officials have free expression","Freedom of expression means voting"],"correctIndex":1,"explanation":"Rights are important, but their exercise occurs within a legal framework and alongside other rights and responsibilities."},{"prompt":"Which action best demonstrates responsible citizenship?","choices":["Ignoring public information","Respecting others'' rights while participating in community life","Sharing unverified claims because they are popular","Refusing every lawful duty"],"correctIndex":1,"explanation":"Responsible citizenship combines participation with respect for rights and lawful obligations."}]}]}}'::jsonb
),
(
'social-studies','a2-electoral-systems','a2-society-governance','24. Electoral Processes and Systems','Follow the election process and distinguish first-past-the-post from proportional representation without partisan framing.',60,true,
'{"syllabus":{"section":"A","part":"ii","objectives":["24"],"source":"CXC 14/G/SYLL 22"},"lesson":{"objectives":["Outline key stages in an electoral process.","Explain responsibilities of electoral bodies, voters, parties, observers and returning officers.","Distinguish first-past-the-post and proportional representation.","Explain advantages and limitations of electoral systems in neutral terms."],"introduction":"An election is a process, not only election day. Before votes are cast there are legal and administrative steps. After voting, ballots must be counted, winners declared and constitutional procedures followed to form a government.","sections":[{"title":"A simplified electoral process","bullets":["The election is called according to constitutional and legal procedures.","The electoral authority prepares the voters'' list, polling arrangements and public instructions.","Political parties and candidates campaign.","Eligible voters meet registration and identification requirements.","Voting takes place at polling stations under established procedures.","Votes are counted and results declared by authorised officials.","The head of government is selected according to the country''s constitutional rules and office holders are sworn in."]},{"title":"Election observers","paragraphs":["Independent observer missions may assess whether an electoral process follows accepted standards. Their presence does not replace the domestic electoral authority. The roles are different."]},{"title":"First-past-the-post","paragraphs":["In a constituency-based first-past-the-post system, the candidate with the most votes in a constituency wins that seat. A party''s share of seats can therefore differ from its share of the national vote."]},{"title":"Proportional representation","paragraphs":["Proportional representation systems aim to allocate seats more closely in relation to vote share. There are several forms of PR, so the precise mechanism depends on the system used.","Comparisons should consider representation, constituency links, simplicity, government formation and how votes are converted into seats. Do not claim that one system is automatically ''best'' without criteria and evidence."]}],"keyPoints":["Election administration involves legal steps before, during and after polling day.","Electoral bodies, parties, voters, observers and returning officers have different roles.","FPTP awards constituency seats to the candidate with the most votes.","PR aims for a closer relationship between vote share and seat share.","Advantages and disadvantages depend on the design and the criterion being considered."],"summary":"For system comparisons, explain how votes become seats. Use neutral, fictional examples when practising calculations or evaluating possible effects.","flashcards":[{"front":"How does FPTP award a constituency seat?","back":"The candidate with the most votes in that constituency wins the seat."},{"front":"What is the basic aim of proportional representation?","back":"To make seat allocation correspond more closely to vote share."},{"front":"What does an electoral authority do?","back":"Administers lawful election procedures such as registration, polling and counting arrangements."},{"front":"What is the role of an election observer mission?","back":"To independently observe and assess aspects of an electoral process."},{"front":"Why can vote share differ from seat share under FPTP?","back":"Seats are won constituency by constituency rather than allocated from total national vote share."}],"interactiveModels":[{"id":"a2-election-system-simulator","type":"social-studies","mode":"choice","title":"Election System Simulator","items":[{"context":"In Constituency North, Candidate A receives 6,200 votes, B 5,900 and C 1,400.","prompt":"Under FPTP, who wins the seat?","choices":["Candidate A","Candidate B","Candidate C","All three share it"],"correctIndex":0,"explanation":"The candidate with the largest number of votes wins the constituency seat."},{"context":"A fictional national system gives parties seats broadly in line with their percentage of votes.","prompt":"Which system is being described?","choices":["FPTP","Proportional representation","Crown Colony government","Autocracy"],"correctIndex":1,"explanation":"PR systems seek a closer relationship between votes received and seats allocated."}]}]}}'::jsonb
),
(
'social-studies','a2-campaign-information-decisions','a2-society-governance','25. Campaigns, Information, Research and Tolerance','Study how parties prepare for elections while learning to distinguish fact, opinion and propaganda and make evidence-based decisions.',70,true,
'{"syllabus":{"section":"A","part":"ii","objectives":["25a","25b","25c","25d","25e"],"source":"CXC 14/G/SYLL 22"},"lesson":{"objectives":["Evaluate common activities used by political parties to prepare for elections.","Distinguish fact, opinion and propaganda using evidence.","Design neutral data-collection tools for public opinion.","Apply a structured decision-making process.","Demonstrate tolerance for different political opinions."],"introduction":"This lesson is less about memorising campaign activities and more about becoming a careful consumer of political information. CSEC expects students to identify evidence, recognise persuasion and collect opinions without manipulating respondents.","sections":[{"title":"How parties prepare","bullets":["Build party and constituency organisation.","Select candidates.","Raise or source campaign financing within applicable rules.","Campaign through face-to-face communication, print, digital media and rallies.","Monitor electoral procedures.","Commission public-opinion research.","Develop and publish a manifesto or policy programme."]},{"title":"Fact, opinion and propaganda","paragraphs":["A fact is a claim that can be checked against evidence. An opinion expresses a judgement or perspective. Propaganda is persuasive communication that may rely heavily on emotion, selective presentation, bias or assumptions while giving inadequate attention to competing evidence.","An opinion is not automatically false, and an emotionally worded statement is not automatically propaganda. Classify the communication from its evidence, purpose and method."]},{"title":"Collecting opinions fairly","paragraphs":["If a survey asks ''Do you support the sensible plan to improve schools?'' the word ''sensible'' pushes respondents. A neutral version describes the proposal without praise or attack and provides balanced response choices. Sampling also matters because a poll of one supportive group cannot safely represent everyone."]},{"title":"A decision-making process","bullets":["Define the problem.","Identify limiting factors.","Develop realistic alternatives.","Analyse advantages, disadvantages and evidence.","Select an alternative using stated criteria.","Implement the decision.","Monitor and evaluate the result."]},{"title":"Tolerance in political discussion","paragraphs":["People may support different parties, support no party or choose not to vote where the law permits. Tolerance means engaging respectfully with lawful opinions without pretending all claims are equally supported by evidence. Critique the argument, not the person''s dignity."]}],"keyPoints":["Campaign preparation includes organisation, candidates, financing, communication, monitoring, polling and manifestos.","Facts are verifiable; opinions express judgements; propaganda uses persuasive techniques that may distort or selectively present evidence.","Opinion research should use neutral questions and appropriate samples.","Decision-making should be explicit and evidence-based.","Tolerance does not require accepting false information as fact."],"summary":"The safest exam method is to identify the type of statement, point to the feature that proves your classification, then explain its likely effect on the audience.","flashcards":[{"front":"What makes a statement a fact?","back":"It can be checked against evidence and verified or disproved."},{"front":"What is an opinion?","back":"A judgement or perspective that is not established simply by factual verification."},{"front":"What is propaganda?","back":"Persuasive messaging that may rely on emotion, bias or selective evidence to influence an audience."},{"front":"Why must opinion-poll questions be neutral?","back":"Leading wording can bias responses and weaken validity."},{"front":"What is the first step in decision-making?","back":"Define the problem clearly."},{"front":"Does tolerance mean every political claim is equally true?","back":"No. Respect people while still checking claims against evidence."}],"interactiveModels":[{"id":"a2-information-literacy","type":"social-studies","mode":"classify","title":"Fact, Opinion or Propaganda?","categories":["Fact","Opinion","Propaganda"],"items":[{"label":"The fictional electoral office reports that 18,420 ballots were counted.","category":"Fact","explanation":"The numerical claim can be checked against an official count."},{"label":"I think the proposed youth centre would be the best use of the land.","category":"Opinion","explanation":"This is a judgement about what would be best."},{"label":"Only a fool would question our perfect plan. Everyone who cares about the country agrees with us.","category":"Propaganda","explanation":"It uses emotional pressure and dismisses other positions instead of providing evidence."},{"label":"A survey of 500 registered voters was conducted between 3 and 5 May.","category":"Fact","explanation":"The claim about the survey method can be verified."}]}]}}'::jsonb
),
(
'social-studies','a2-election-data','a2-society-governance','26–28. Election Outcomes, Statistical Data and Conclusions','Analyse the factors that can influence elections and practise reading tables, graphs, polls and other election data without making unsupported claims.',80,true,
'{"syllabus":{"section":"A","part":"ii","objectives":["26","27","28"],"source":"CXC 14/G/SYLL 22"},"lesson":{"objectives":["Outline factors that may influence election outcomes.","Identify trends and patterns in election data.","Summarise statistical information accurately.","Draw conclusions that are supported by the data presented."],"introduction":"Election data can tell you what happened in a sample, constituency or election. It cannot automatically tell you why it happened. CSEC expects students to distinguish description from explanation and to avoid conclusions that go beyond the evidence.","sections":[{"title":"Factors that may influence outcomes","bullets":["Traditional and social-media coverage.","Campaign advertising and strategy.","Public opinion polls.","Voters'' ability to analyse information.","Voter turnout, age, education, party loyalty, attitudes and motivation.","Candidates and national issues.","Economic circumstances and campaign spending."]},{"title":"Read the data before explaining","paragraphs":["Suppose turnout falls from 68% to 59%. You may state that turnout decreased by 9 percentage points. You cannot conclude from that number alone that ''young people became apathetic''. You would need age-specific data or other evidence.","Always check the title, unit, date, population and source before interpreting a table or chart."]},{"title":"Trend, pattern and comparison","bullets":["Trend: a general direction over time, such as rising or falling turnout.","Pattern: a repeated or noticeable relationship in the data.","Comparison: a statement showing how categories differ, ideally with numbers.","Anomaly: a value that differs noticeably from the surrounding pattern and may need explanation."]},{"title":"Drawing a supported conclusion","paragraphs":["A conclusion is a logical summary supported by evidence. State the evidence in the same sentence or the next one. For example: ''In the fictional data, turnout was highest among the 45–64 group at 72%, so participation was not evenly distributed across age groups.''"]}],"keyPoints":["Election outcomes can be influenced by many interacting factors.","Data describe observed patterns but do not automatically prove causes.","Use exact numbers when comparing categories.","A conclusion must be supported by evidence from the source."],"summary":"Use the phrase ''the data show'' only for what the data actually show. Use ''may suggest'' when interpretation is reasonable but not proven.","flashcards":[{"front":"What is a trend?","back":"A general direction of change shown by data over time."},{"front":"What is a pattern?","back":"A repeated or noticeable relationship in a set of data."},{"front":"Why can''t correlation alone prove an election cause?","back":"Two variables can move together without showing which factor caused the result."},{"front":"What should a statistical conclusion include?","back":"A logical statement supported by specific evidence from the data."},{"front":"What is a percentage-point change?","back":"The arithmetic difference between two percentages."}],"interactiveModels":[{"id":"a2-election-data-lab","type":"social-studies","mode":"choice","title":"Election Data Lab","items":[{"context":"Fictional turnout: 2022 = 64%; 2026 = 58%.","prompt":"Which conclusion is directly supported?","choices":["Voters disliked every candidate","Turnout fell by 6 percentage points","Social media caused lower turnout","Young voters stopped voting"],"correctIndex":1,"explanation":"Only the change in turnout is directly shown. The reasons need additional evidence."},{"context":"Fictional poll: 18–29: 44% likely to vote; 30–44: 61%; 45–64: 73%; 65+: 70%.","prompt":"Which summary is best?","choices":["Age causes voting","The 45–64 group records the highest stated likelihood in this sample","Everyone over 45 will vote","Young people are irresponsible"],"correctIndex":1,"explanation":"It accurately describes the sample without turning association into causation or stereotype."},{"context":"Party X receives 48% of votes and 60% of seats in a fictional FPTP election.","prompt":"What can be safely concluded?","choices":["The count must be wrong","Seat share is higher than vote share","Party X is the best party","PR was used"],"correctIndex":1,"explanation":"The numerical comparison is supported; value judgements and causal claims are not."}]}]}}'::jsonb
),
(
'social-studies','a2-governance-citizenship','a2-society-governance','29–30. Good Governance and Good Citizenship','Connect accountable public institutions with active, informed and responsible citizenship.',90,true,
'{"syllabus":{"section":"A","part":"ii","objectives":["29","30"],"source":"CXC 14/G/SYLL 22"},"lesson":{"objectives":["Identify characteristics of good governance.","Explain why transparency, accountability, participation and judicial independence matter.","Identify characteristics and duties associated with good citizenship.","Explain the interdependence of citizens, institutions and government."],"introduction":"Governance is the process through which public decisions are made, implemented and reviewed. Citizenship is the way individuals belong to and participate in a political community. Strong societies require responsible institutions and responsible participation.","sections":[{"title":"Characteristics of good governance","bullets":["Participation and inclusiveness.","Independence of the judiciary.","Transparency and access to information.","Accountability for decisions and use of resources.","Responsiveness to citizens'' needs.","Service of the wider public good.","Prudent use of public resources.","An efficient civil service.","Consultation and tolerance of freedom of expression.","Capacity for creativity and innovation."]},{"title":"Transparency and accountability are different","paragraphs":["Transparency makes relevant information and processes visible or accessible. Accountability requires decision-makers to explain actions and face appropriate consequences or correction when standards are not met. Transparency can support accountability, but they are not identical."]},{"title":"Good citizenship","bullets":["Active and informed participation in community and civic life.","Respect for human rights and the rights of others.","Obeying lawful rules and fulfilling civic responsibilities.","Environmental responsibility.","Healthy lifestyle practices and concern for others.","Productive participation in society.","Patriotism that can include constructive concern for improving one''s country."]},{"title":"Citizens and government depend on each other","paragraphs":["Government needs citizens to obey law, pay required taxes, provide accurate information, participate and hold institutions accountable through lawful channels. Citizens depend on government for security, services, infrastructure, rights protection and fair administration. This is interdependence, not blind agreement."]}],"keyPoints":["Good governance includes participation, transparency, accountability, responsiveness and judicial independence.","Transparency is access to information; accountability is answerability for decisions and performance.","Good citizenship combines rights with civic responsibility.","Constructive criticism and lawful participation can be forms of citizenship."],"summary":"When asked to assess governance, name a criterion and apply it to evidence. Do not decide whether a real government is ''good'' or ''bad'' without a clearly defined criterion and reliable evidence.","flashcards":[{"front":"What is transparency in governance?","back":"Openness and access to relevant information about decisions, processes and public resources."},{"front":"What is accountability?","back":"Being answerable for decisions and performance and subject to review or consequences."},{"front":"Why does judicial independence matter?","back":"Courts should decide cases according to law without improper political pressure."},{"front":"Give two characteristics of good citizenship.","back":"Examples: informed participation, respect for rights, lawfulness or environmental responsibility."},{"front":"How are citizens and government interdependent?","back":"Each relies on the other for lawful participation, services, order, accountability and rights protection."}],"interactiveModels":[{"id":"a2-governance-check","type":"social-studies","mode":"classify","title":"Governance Principle Check","categories":["Transparency","Accountability","Participation","Responsiveness","Judicial independence"],"items":[{"label":"A ministry publishes detailed procurement information for public inspection.","category":"Transparency"},{"label":"An official must explain spending decisions to an oversight body.","category":"Accountability"},{"label":"Residents are invited to submit views before a local development plan is finalised.","category":"Participation"},{"label":"A public agency changes a service after repeated evidence of access problems.","category":"Responsiveness"},{"label":"Judges decide cases without direction from ministers or political parties.","category":"Judicial independence"}]}]}}'::jsonb
)
